import {equipment,reagents,controls,kind,makeItem,validLink,validateSetup,mixtureInfo,createRun,step,preset} from './engine.js';
import {BuilderScene} from './scene.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toString():'—';
let setup=preset('freeze'),selected=setup.items[0]?.id,run=createRun(setup),running=false,history=[],samples=[],library=[],notes='',scene,last=performance.now(),uiTime=0,sampleTime=-1;
const say=text=>$('#status').textContent=text;
try{const saved=JSON.parse(localStorage.getItem('chemia-builder-library-v1')||'[]');if(Array.isArray(saved))library=saved.filter(x=>x&&typeof x.id==='string'&&x.setup).slice(0,50);}catch{say('Saved setups could not be read. You can still import a JSON file.');}
try{scene=new BuilderScene($('#scene'),$('#labels'),select,(id,pos)=>{edit(()=>Object.assign(setup.items.find(i=>i.id===id),pos));});}catch(e){$('#fallback').hidden=false;say('WebGL unavailable; use the controls and measurements below.');}
const item=()=>setup.items.find(i=>i.id===selected);
const itemName=id=>{const i=setup.items.find(i=>i.id===id);return i?equipment[i.type].name+' '+i.id.replace('i',''):id;};
function snapshot(){return JSON.stringify({setup,notes});}
function edit(fn){history.push(snapshot());if(history.length>40)history.shift();fn();restart();render();say('Setup updated. Simulation restarted; press Run to test it.');}
function restart(){running=false;run=createRun(setup);samples=[];sampleTime=-1;$('#run').textContent='▶ Run experiment';}
function select(id){selected=id;$('#selected').value=id;inspector();metrics();live();graph();}
function shelf(){const q=$('#search').value.toLowerCase();let html='',group='';for(const [type,e]of Object.entries(equipment).filter(([,e])=>e.name.toLowerCase().includes(q))){if(e.group!==group){html+=`<h3>${e.group}</h3>`;group=e.group;}html+=`<button draggable="true" data-add="${type}" title="Click to add; then drag on the bench"><span>${e.icon}</span>${e.name} ＋</button>`;}$('#equipment').innerHTML=html||'<p>No apparatus found.</p>';}
$('#search').oninput=shelf;
function add(type,x,z){if(setup.items.length>=30){say('Bench limit: 30 apparatus. Remove an item first.');return;}edit(()=>{const id='i'+Math.max(1,...setup.items.map(i=>(Number(i.id.slice(1))||0)+1));let i=makeItem(type,id,x??((setup.items.length%4)-1.5)*2.2,z??(Math.floor(setup.items.length/4)%3-1)*2.1);setup.items.push(i);selected=id;});}
$('#equipment').onclick=e=>{const b=e.target.closest('[data-add]');if(b)add(b.dataset.add);};
$('#equipment').ondragstart=e=>{const b=e.target.closest('[data-add]');if(b)e.dataTransfer.setData('text/plain',b.dataset.add);};
$('#viewport').ondragover=e=>e.preventDefault();$('#viewport').ondrop=e=>{e.preventDefault();const type=e.dataTransfer.getData('text/plain');if(equipment[type])add(type);};
function render(){if(!setup.items.some(i=>i.id===selected))selected=setup.items[0]?.id||'';$('#selected').innerHTML='<option value="">Choose an item…</option>'+setup.items.map(i=>`<option value="${i.id}">${esc(itemName(i.id))}</option>`).join('');$('#selected').value=selected;$('#itemcount').textContent=setup.items.length+' apparatus';$('#empty').hidden=!!setup.items.length;$('#name').value=setup.name;$('#notes').value=notes;$('#undo').disabled=!history.length;scene?.build(setup);inspector();metrics();connections();live();graph();}
function settingsFor(i){const k=kind(i);return (controls[k]||[]).filter(c=>{if(k==='vessel')return c[0]==='temperature';if(k==='thermal')return c[0]==='power'||i.type==='burner';if(k==='electrical')return i.type==='battery'?c[0]==='voltage':i.type==='switch'?false:c[0]==='resistance'||(i.type==='bulb'&&c[0]==='rating');return true;});}
function inspector(){const i=item();if(!i){$('#inspector').innerHTML='<p>Select an apparatus on the bench or add one from the shelf.</p>';return;}let html=`<p><b>${esc(equipment[i.type].name)}</b><br>${kind(i)==='chamber'||kind(i)==='pump'?'Fictional stress model. Values are arbitrary demonstration units.':'Change settings while paused; edits restart the experiment.'}</p><div class="pair"><label>Position X<input data-position="x" type="number" min="-6" max="6" step=".1" value="${i.x.toFixed(1)}"></label><label>Position Z<input data-position="z" type="number" min="-5" max="5" step=".1" value="${i.z.toFixed(1)}"></label></div>`;
 html+=settingsFor(i).map(([key,label,unit,min,max,inc])=>`<label>${label} (${unit})<input data-setting="${key}" type="number" min="${min}" max="${max}" step="${inc}" value="${i.settings[key]}"></label>`).join('');
 if(i.type==='switch')html+=`<label>Switch position<select data-switch><option value="closed" ${i.settings.closed?'selected':''}>Closed</option><option value="open" ${!i.settings.closed?'selected':''}>Open</option></select></label>`;
 if(kind(i)==='vessel'){html+=`<h3>Contents</h3><div class="mixture">${i.mixture.map(r=>`${esc(reagents[r.id].name)} · ${r.ml} mL`).join('<br>')||'Empty vessel'}<br><b>${i.mixture.reduce((s,r)=>s+r.ml,0)} / 500 mL</b></div><label>Add reagent<select id="reagent">${Object.entries(reagents).map(([id,r])=>`<option value="${id}">${esc(r.name)}</option>`).join('')}</select></label><label>Amount (mL)<input id="amount" type="number" min="1" max="500" step="1" value="25"></label><button id="add-reagent">＋ Add reagent</button> <button id="empty-vessel">Empty vessel</button><p>${esc(mixtureInfo(i.mixture).status)}. Aqueous heat properties approximate those of water.</p>`;}
 if(i.type==='condenser')html+='<p>Connect vessel → condenser → collection vessel. Ideal condenser captures all modeled vapor; coolant flow is assumed.</p>';
 if(i.type==='pendulum')html+='<p>Connect a stand using a support link. Small-angle, undamped pendulum; use length and gravity to compare periods.</p>';
 if(kind(i)==='electrical')html+='<p>Terminal A is red; B is dark. Connect both terminals to form a closed circuit. One DC supply per bench; resistive components only.</p>';
 html+='<hr><button id="duplicate">Duplicate apparatus</button> <button id="remove" class="danger">Remove</button>';$('#inspector').innerHTML=html;
}
$('#selected').onchange=()=>select($('#selected').value);
$('#inspector').onchange=e=>{const i=item(),el=e.target;if(!i)return;if(el.matches('[data-setting],[data-position]')){if(!el.checkValidity()){el.reportValidity();return;}edit(()=>{if(el.dataset.setting)i.settings[el.dataset.setting]=Number(el.value);else i[el.dataset.position]=Number(el.value);});}if(el.matches('[data-switch]'))edit(()=>i.settings.closed=el.value==='closed');};
$('#inspector').onclick=e=>{const i=item();if(!i)return;if(e.target.id==='remove')edit(()=>{setup.items=setup.items.filter(x=>x!==i);setup.links=setup.links.filter(l=>l.from!==i.id&&l.to!==i.id);});if(e.target.id==='duplicate'){if(setup.items.length>=30){say('Bench limit: 30 apparatus.');return;}edit(()=>{let copy=JSON.parse(JSON.stringify(i));copy.id='i'+Math.max(1,...setup.items.map(a=>(Number(a.id.slice(1))||0)+1));copy.x=Math.min(6,i.x+1.5);setup.items.push(copy);selected=copy.id;});}if(e.target.id==='empty-vessel')edit(()=>i.mixture=[]);if(e.target.id==='add-reagent'){const amount=$('#amount');if(!amount.checkValidity()){amount.reportValidity();return;}const ml=Number(amount.value),id=$('#reagent').value;if(i.mixture.reduce((s,r)=>s+r.ml,0)+ml>500){say('The vessel capacity is 500 mL. Empty it or add less.');return;}edit(()=>{let existing=i.mixture.find(r=>r.id===id);if(existing)existing.ml+=ml;else i.mixture.push({id,ml});});}};
function connections(){const value=$('#linkkind').value;const allowedFrom=i=>value==='wire'?kind(i)==='electrical':value==='thermal'?kind(i)==='thermal':value==='support'?kind(i)==='stand':['pump','vessel','tube'].includes(kind(i));const allowedTo=i=>value==='wire'?kind(i)==='electrical':value==='thermal'?kind(i)==='vessel':value==='support'?kind(i)==='pendulum':['chamber','tube','collector'].includes(kind(i));for(const [id,filter]of [['from',allowedFrom],['to',allowedTo]]){const prev=$('#'+id).value;$('#'+id).innerHTML=setup.items.filter(filter).map(i=>`<option value="${i.id}">${esc(itemName(i.id))}</option>`).join('');if([...$('#'+id).options].some(o=>o.value===prev))$('#'+id).value=prev;}document.querySelectorAll('.port').forEach(el=>el.hidden=value!=='wire');$('#links').innerHTML=setup.links.map((l,j)=>`<div class="linkrow"><span>${esc(itemName(l.from))}${l.kind==='wire'?' · '+l.fromPort:''}<br>↳ ${esc(itemName(l.to))}${l.kind==='wire'?' · '+l.toPort:''} (${l.kind})</span><button data-unlink="${j}" aria-label="Remove connection ${j+1}">×</button></div>`).join('')||'<p class="fine">No connections. Select a compatible pair and connect.</p>';}
$('#linkkind').onchange=connections;
$('#connect').onsubmit=e=>{e.preventDefault();const l={kind:$('#linkkind').value,from:$('#from').value,to:$('#to').value,fromPort:$('#fromport').value,toPort:$('#toport').value};if(!validLink(setup.items,l)){say('Unsupported connection. Read “Supported rules” for compatible apparatus.');return;}if(setup.links.length>=80){say('Maximum 80 connections.');return;}if(setup.links.some(x=>JSON.stringify(x)===JSON.stringify(l))){say('That connection already exists.');return;}if(l.kind==='tube'&&setup.links.some(x=>x.kind==='tube'&&x.from===l.from)){say('Each tube source supports one outlet. Remove its existing tube first.');return;}edit(()=>setup.links.push(l));};
$('#links').onclick=e=>{const b=e.target.closest('[data-unlink]');if(b)edit(()=>setup.links.splice(Number(b.dataset.unlink),1));};
function load(next,n=''){edit(()=>{setup=validateSetup(next);notes=n;selected=setup.items[0]?.id||'';});}
$('#preset').onchange=()=>{const name=$('#preset').value;if(!name)return;load(preset(name));$('#speed').value=['freeze','boil'].includes(name)?'20':'1';$('#preset').value='';say('Template loaded. Modify any apparatus or connection, then Run.');};
$('#undo').onclick=()=>{if(!history.length)return;const old=JSON.parse(history.pop());setup=old.setup;notes=old.notes;restart();render();say('Previous setup restored.');};
function tick(dt){step(setup,run,dt);if(run.time-sampleTime>=.5){samples.push({time:run.time,states:JSON.parse(JSON.stringify(run.states))});if(samples.length>600)samples.shift();sampleTime=run.time;}}
$('#run').onclick=()=>{if(!setup.items.length){say('Add apparatus or load a template first.');return;}running=!running;$('#run').textContent=running?'Ⅱ Pause experiment':'▶ Resume experiment';say(running?'Experiment running. Select apparatus to inspect its measurements.':'Paused. Reset & repair starts a fresh run.');};
$('#step').onclick=()=>{running=false;$('#run').textContent='▶ Resume experiment';tick(1);live();graph();};
$('#reset').onclick=()=>{restart();live();graph();say('Simulation reset. All equipment repaired; initial contents restored.');};
function live(){const i=item(),s=run.states[selected];$('#time').textContent=run.time.toFixed(1)+' s';if(!i||!s){$('#readings').innerHTML='<p class="fine">Select apparatus to inspect its readings.</p>';$('#events').innerHTML='';return;}const rows=[];if(kind(i)==='vessel'){if(!i.mixture.length)rows.push(['Contents','Empty; no thermal model']);else{rows.push(['Temperature',fmt(s.temperature)+' °C'],['Phase',s.phase],['Ice fraction',fmt(s.ice*100)+' %'],['Vaporized fraction',fmt(s.vapor*100)+' %']);const mix=s.mix||mixtureInfo(i.mixture);rows.push(['Chemistry',mix.status]);if(mix.precipitate)rows.push(['Ideal precipitate mass',fmt(mix.precipitate*1000)+' g']);}}
 if(i.type==='collector')rows.push(['Condensate collected',fmt(s.condensate)+' g']);if(i.type==='chamber')rows.push(['Fictional stress',fmt(s.stress)+' units'],['Equipment',s.broken?'RUPTURED — reset to repair':'Intact']);if(kind(i)==='electrical')rows.push(['Voltage',fmt(s.voltage)+' V'],['Current',fmt(s.current)+' A'],['Power',fmt(s.power)+' W'],['Circuit',run.circuitStatus||'Run to solve connections'],['Equipment',s.broken?'DAMAGED — reset to repair':'Intact']);if(kind(i)==='thermal')rows.push(['Heat-transfer setting',fmt(i.settings.power)+' W'],['Smoke',s.smoke?'Visible • illustrative':'None']);if(i.type==='pendulum')rows.push(['Support',s.supported?'Connected':'Connect a stand'],['Period',fmt(s.period)+' s'],['Angle',fmt(s.angle*180/Math.PI)+' °']);if(!rows.length)rows.push(['Role',equipment[i.type].name],['Status','Connect to compatible apparatus']);$('#readings').innerHTML=rows.map(([k,v])=>`<div class="reading"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');const eventText=run.events.slice(0,3).map(e=>`${e.time.toFixed(1)} s · ${e.text}`).join('\n');if($('#events').dataset.text!==eventText){$('#events').dataset.text=eventText;$('#events').innerHTML=run.events.slice(0,3).map(e=>`<div class="event">${e.time.toFixed(1)} s · ${esc(e.text)}</div>`).join('');}}
const metricLabels={temperature:'Temperature (°C)',ice:'Ice fraction',vapor:'Vapor fraction',stress:'Fictional stress (units)',current:'Current (A)',voltage:'Voltage (V)',power:'Electrical power (W)',condensate:'Collected condensate (g)',angle:'Pendulum angle (rad)'};
const metricKeys=i=>!i?[]:kind(i)==='vessel'?['temperature','ice','vapor']:kind(i)==='electrical'?['current','voltage','power']:i.type==='chamber'?['stress']:i.type==='collector'?['condensate']:i.type==='pendulum'?['angle']:[];
function metrics(){const previous=$('#metric').value,keys=metricKeys(item());$('#metric').innerHTML=keys.length?keys.map(k=>`<option value="${k}">${metricLabels[k]}</option>`).join(''):'<option value="">No plottable measurement</option>';if(keys.includes(previous))$('#metric').value=previous;}
function graph(){const metric=$('#metric').value,pts=samples.map(r=>[r.time,r.states[selected]?.[metric]]).filter(p=>p.every(Number.isFinite));$('#samples').textContent=`${pts.length} samples · ${item()?itemName(selected):'No apparatus selected'} · ${$('#metric').selectedOptions[0].textContent}`;if(pts.length<2){$('#graph').innerHTML='<p class="fine">Run the experiment to plot the selected measurement for this apparatus.</p>';return;}let xmin=pts[0][0],xmax=pts.at(-1)[0],min=Math.min(...pts.map(p=>p[1])),max=Math.max(...pts.map(p=>p[1]));if(min===max){min-=.5;max+=.5;}const px=x=>55+(x-xmin)/Math.max(.01,xmax-xmin)*620,py=y=>175-(y-min)/(max-min)*150;$('#graph').innerHTML=`<svg viewBox="0 0 740 220" role="img" aria-label="${esc($('#metric').selectedOptions[0].textContent)} against simulation time"><path d="M55 15V175H690" fill="none" stroke="#a7bba2"/><polyline fill="none" stroke="#39866c" stroke-width="2" points="${pts.map(([x,y])=>`${px(x)},${py(y)}`).join(' ')}"/><g font-size="10" fill="#7b9275"><text x="0" y="25">${fmt(max)}</text><text x="0" y="175">${fmt(min)}</text><text x="55" y="195">${fmt(xmin)}</text><text x="650" y="195">${fmt(xmax)}</text><text x="310" y="215">Simulation time (s)</text></g></svg>`;}
$('#metric').onchange=graph;
$('#name').onchange=()=>setup.name=$('#name').value||'My custom experiment';$('#notes').oninput=()=>notes=$('#notes').value;
function savedOptions(){ $('#saved').innerHTML='<option value="">Open saved setup…</option>'+library.map(s=>`<option value="${esc(s.id)}">${esc(s.setup.name)}</option>`).join('');}
$('#save').onclick=()=>{try{const entry={id:crypto.randomUUID(),setup:validateSetup(setup),notes};const next=[entry,...library].slice(0,50);localStorage.setItem('chemia-builder-library-v1',JSON.stringify(next));library=next;savedOptions();say('Setup and notes saved in this browser. Export JSON for a portable copy.');}catch(e){say('Could not save: '+e.message+' Export JSON to keep your setup.');}};
$('#saved').onchange=()=>{const entry=library.find(s=>s.id===$('#saved').value);if(entry){try{load(entry.setup,String(entry.notes||''));say('Saved setup reopened. Press Run to start a fresh experiment.');}catch(e){say('Cannot open setup: '+e.message);}}$('#saved').value='';};
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>download('chemia-custom-lab.json',JSON.stringify({...setup,notes},null,2),'application/json');
$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>250000)throw Error('File exceeds 250 KB.');const raw=JSON.parse(await f.text());const next=validateSetup(raw);load(next,String(raw.notes||'').slice(0,20000));say('Imported setup. Press Run to test it.');}catch(err){say('Import rejected: '+err.message);}e.target.value='';};
const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';
$('#csv').onclick=()=>{if(!samples.length){say('Run the experiment to collect readings first.');return;}const keys=['temperature','ice','vapor','stress','current','voltage','power','condensate','angle','broken'];const rows=[['Time (s)','Apparatus','Type','Temperature (°C)','Ice fraction','Vapor fraction','Fictional stress','Current (A)','Voltage (V)','Power (W)','Condensate (g)','Angle (rad)','Damaged']];for(const r of samples)for(const i of setup.items)rows.push([r.time,i.id,equipment[i.type].name,...keys.map(k=>k==='broken'?r.states[i.id][k]:metricKeys(i).includes(k)?r.states[i.id][k]:'')]);download('chemia-custom-readings.csv',rows.map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv');};
$('#report').onclick=()=>download('chemia-custom-report.md',`# ${setup.name}\n\n## Setup\n${setup.items.map(i=>`- ${itemName(i.id)}: ${JSON.stringify(i.settings)}; contents ${JSON.stringify(i.mixture)}`).join('\n')}\n\n## Connections\n${setup.links.map(l=>`- ${l.kind}: ${itemName(l.from)} ${l.fromPort} → ${itemName(l.to)} ${l.toPort}`).join('\n')}\n\n## Observations\n${notes}\n\n## Events\n${run.events.map(e=>`${e.time.toFixed(1)} s: ${e.text}`).join('\n')}\n\n## Model limitations\nIdeal water heat/phase model for all aqueous solutions; no heat loss, gas dynamics or real apparatus calibration. Mixture rules are a finite library. DC circuits use fixed resistances. Smoke, flames and damage are illustrative. Stress-source/chamber units and failure thresholds are fictional and cannot predict real explosion or rupture behavior. See CSV for run readings.\n`,'text/markdown');
$('#left').onclick=()=>scene?.rotate(-.25);$('#right').onclick=()=>scene?.rotate(.25);$('#zoomIn').onclick=()=>scene?.zoom(-1.5);$('#zoomOut').onclick=()=>scene?.zoom(1.5);
$('#motion').checked=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(running){let remaining=dt*Number($('#speed').value);while(remaining>0){let d=Math.min(.1,remaining);tick(d);remaining-=d;}if(run.time>=600){running=false;$('#run').textContent='▶ Resume experiment';say('Paused at 600 simulated seconds. Export readings or reset for another run.');}}scene?.update(run,selected,$('#motion').checked);if(running&&now-uiTime>150){live();graph();uiTime=now;}requestAnimationFrame(frame);}
shelf();savedOptions();render();requestAnimationFrame(frame);
