// Original educational models. Fictional failure effects are deliberately non-predictive.
export const equipment={
 beaker:{name:'Beaker',icon:'⚗',group:'Chemistry',kind:'vessel'},flask:{name:'Conical flask',icon:'♧',group:'Chemistry',kind:'vessel'},
 heater:{name:'Hot plate',icon:'♨',group:'Thermal',kind:'thermal'},cooler:{name:'Cooling bath',icon:'❄',group:'Thermal',kind:'thermal'},burner:{name:'Burner',icon:'♨',group:'Thermal',kind:'thermal'},
 condenser:{name:'Condenser',icon:'≋',group:'Chemistry',kind:'tube'},collector:{name:'Collection vessel',icon:'▱',group:'Chemistry',kind:'collector'},
 chamber:{name:'Fictional pressure chamber',icon:'◉',group:'Effects',kind:'chamber'},pump:{name:'Fictional stress source',icon:'↟',group:'Effects',kind:'pump'},
 battery:{name:'DC supply',icon:'▰',group:'Electricity',kind:'electrical'},resistor:{name:'Resistor',icon:'▨',group:'Electricity',kind:'electrical'},bulb:{name:'Lamp',icon:'☼',group:'Electricity',kind:'electrical'},switch:{name:'Switch',icon:'⌁',group:'Electricity',kind:'electrical'},
 stand:{name:'Retort stand',icon:'⊥',group:'Mechanics',kind:'stand'},pendulum:{name:'Pendulum bob',icon:'●',group:'Mechanics',kind:'pendulum'}
};
export const reagents={water:{name:'Water',color:0x80c9de},saltwater:{name:'Salt solution',color:0x92d1d5},dye:{name:'Blue dye',color:0x347ed6},acid:{name:'Dilute acid (0.1 M)',color:0xa2d9e0},base:{name:'Dilute base (0.1 M)',color:0xabe0ca},indicator:{name:'Universal indicator (visual)',color:0x62c78e},calcium:{name:'Calcium chloride (0.1 M)',color:0xb3dfeb},carbonate:{name:'Sodium carbonate (0.1 M)',color:0xc3e5df},tablet:{name:'Effervescent sample (visual)',color:0xf0cc7a}};
export const controls={
 vessel:[['volume','Initial sample','mL',10,500,10],['temperature','Initial temperature','°C',-20,100,1]],
 thermal:[['power','Heat transfer magnitude','W',0,1500,50],['oxygen','Oxygen availability (visual)','%',0,100,5]],
 chamber:[['limit','Fictional failure limit','units',10,100,5]],pump:[['rate','Fictional stress input','units/s',0,20,1]],
 electrical:[['voltage','Supply voltage','V',0,24,.5],['resistance','Resistance','Ω',1,1000,1],['rating','Nominal lamp power','W',.1,20,.1]],
 pendulum:[['length','String length','m',.2,3,.1],['gravity','Gravity','m/s²',1,20,.1],['angle','Release angle','°',1,15,1]]
};
export function makeItem(type,id,x=0,z=0){if(!equipment[type])throw Error('Unknown apparatus');return {id,type,x,z,settings:{volume:100,temperature:20,power:type==='cooler'?1000:500,oxygen:100,limit:40,rate:8,voltage:6,resistance:type==='bulb'?20:100,rating:2,length:1,gravity:9.8,angle:12,closed:true},mixture:equipment[type].kind==='vessel'?[{id:'water',ml:100}]:[]};}
export const kind=i=>equipment[i.type].kind;
export function validLink(items,l){const a=items.find(i=>i.id===l.from),b=items.find(i=>i.id===l.to);if(!a||!b||a===b)return false;if(l.kind==='wire')return kind(a)==='electrical'&&kind(b)==='electrical'&&['A','B'].includes(l.fromPort)&&['A','B'].includes(l.toPort);if(l.kind==='thermal')return kind(a)==='thermal'&&kind(b)==='vessel';if(l.kind==='support')return kind(a)==='stand'&&kind(b)==='pendulum';if(l.kind==='tube')return (kind(a)==='pump'&&kind(b)==='chamber')||(kind(a)==='vessel'&&kind(b)==='tube')||(kind(a)==='tube'&&kind(b)==='collector');return false;}
export function validateSetup(raw){if(!raw||raw.version!==1||!Array.isArray(raw.items)||!Array.isArray(raw.links)||raw.items.length>30||raw.links.length>80)throw Error('Use a Chemia builder file (up to 30 items and 80 connections).');const seen=new Set();const items=raw.items.map(i=>{if(!i||typeof i.id!=='string'||!/^[a-zA-Z0-9_-]{1,60}$/.test(i.id)||seen.has(i.id)||!equipment[i.type])throw Error('Invalid or duplicate apparatus.');seen.add(i.id);const n=makeItem(i.type,i.id);for(const key of ['x','z']){if(!Number.isFinite(i[key])||Math.abs(i[key])>7)throw Error('Apparatus outside the bench.');n[key]=i[key];}for(const [key,,,min,max]of Object.values(controls).flat()){if(i.settings?.[key]!==undefined){const v=i.settings[key];if(!Number.isFinite(v)||v<min||v>max)throw Error('Invalid apparatus setting: '+key);n.settings[key]=v;}}n.settings.closed=i.settings?.closed!==false;if(kind(n)==='vessel'){if(!Array.isArray(i.mixture)||i.mixture.length>20)throw Error('Invalid mixture.');n.mixture=i.mixture.map(r=>{if(!reagents[r.id]||!Number.isFinite(r.ml)||r.ml<=0||r.ml>500)throw Error('Invalid reagent amount.');return {id:r.id,ml:r.ml};});if(n.mixture.reduce((s,r)=>s+r.ml,0)>500)throw Error('Vessel capacity is 500 mL.');}return n;});const tubeSources=new Set();const links=raw.links.map(l=>{if(!l||!validLink(items,l))throw Error('Unsupported apparatus connection.');if(l.kind==='tube'){if(tubeSources.has(l.from))throw Error('Each tube source supports one outlet.');tubeSources.add(l.from);}return {kind:l.kind,from:l.from,to:l.to,fromPort:l.fromPort||'A',toPort:l.toPort||'A'};});return {version:1,name:String(raw.name||'Untitled experiment').slice(0,80),items,links};}
export function mixtureInfo(mixture){if(!mixture.length)return {color:0x80c9de,precipitate:0,bubbles:false,status:'Empty vessel',unsupported:false};const ids=new Set(mixture.map(r=>r.id)),ml=id=>mixture.filter(r=>r.id===id).reduce((s,r)=>s+r.ml,0);let color=0x80c9de,precipitate=0,bubbles=false,status='Water / aqueous sample';let unsupported=false;
 if(ids.has('tablet')){bubbles=true;status='Effervescence • illustrative gas evolution';color=0xe8d99b;unsupported=[...ids].some(x=>!['water','tablet'].includes(x));}
 else if(ids.has('calcium')&&ids.has('carbonate')){precipitate=Math.min(ml('calcium'),ml('carbonate'))*.0001*.10009;status='White calcium carbonate precipitate • ideal stoichiometry';color=0xe7eee4;unsupported=[...ids].some(x=>!['water','calcium','carbonate'].includes(x));}
 else if([...ids].every(x=>['water','acid','base','indicator'].includes(x))){const V=mixture.reduce((s,r)=>s+r.ml,0)/1000;const excess=(ml('base')-ml('acid'))*.0001/Math.max(.001,V);const H=(-excess+Math.sqrt(excess*excess+4e-14))/2;const ph=excess>0?14+Math.log10((excess+Math.sqrt(excess*excess+4e-14))/2):-Math.log10(H);status=`Ideal strong acid/base pH ${ph.toFixed(2)}`;if(ids.has('indicator'))color=ph<4?0xe05f58:ph>10?0x815bc5:0x65bd81;return {color,precipitate,bubbles,status,unsupported:false,ph};}
 else if(ids.has('dye')){color=0x347ed6;status='Blue coloration • no reaction modeled';unsupported=[...ids].some(x=>!['water','dye'].includes(x));}
 else if(ids.size===1){color=reagents[[...ids][0]].color;status=reagents[[...ids][0]].name;}
 else unsupported=[...ids].some(x=>!['water','saltwater'].includes(x));
 if(unsupported){status='Combination not modeled. No reaction prediction.';bubbles=false;precipitate=0;color=0xa5b5b8;}
 return {color,precipitate,bubbles,status,unsupported};}
const LF=334000,CW=4184,CI=2100,LV=2256000;
export function thermalState(h,m){const q=h/m;if(q<0)return {temperature:q/CI,ice:1,vapor:0,phase:'Frozen'};if(q<LF)return {temperature:0,ice:1-q/LF,vapor:0,phase:'Freezing / melting'};if(q<LF+CW*100)return {temperature:(q-LF)/CW,ice:0,vapor:0,phase:'Liquid'};return {temperature:100,ice:0,vapor:Math.min(1,(q-LF-CW*100)/LV),phase:q>=LF+CW*100+LV?'Vaporized':'Boiling'};}
export function createRun(setup){return {time:0,events:[],states:Object.fromEntries(setup.items.map(i=>{const mass=Math.max(.01,i.mixture.reduce((s,r)=>s+r.ml,0)/1000);const t=i.settings.temperature;return [i.id,{mass,h:mass*(t<0?CI*t:LF+CW*t),...thermalState(mass*(t<0?CI*t:LF+CW*t),mass),stress:0,broken:false,smoke:false,burstAt:null,condensate:0,current:0,voltage:0,power:0}];}))};}
function solve(A,b){const n=b.length;for(let k=0;k<n;k++){let pivot=k;for(let i=k+1;i<n;i++)if(Math.abs(A[i][k])>Math.abs(A[pivot][k]))pivot=i;if(Math.abs(A[pivot][k])<1e-12)return null;[A[k],A[pivot]]=[A[pivot],A[k]];[b[k],b[pivot]]=[b[pivot],b[k]];let d=A[k][k];for(let j=k;j<n;j++)A[k][j]/=d;b[k]/=d;for(let i=0;i<n;i++)if(i!==k){let f=A[i][k];for(let j=k;j<n;j++)A[i][j]-=f*A[k][j];b[i]-=f*b[k];}}return b;}
export function circuit(setup,states={}){const all=setup.items.filter(i=>kind(i)==='electrical'),batteries=all.filter(i=>i.type==='battery');const out={status:'Add one supply and connect a complete circuit.',values:{}};if(!all.length)return out;if(batteries.length!==1){out.status='Exactly one DC supply is supported per bench.';return out;}let parent={};for(const i of all)for(const p of ['A','B'])parent[i.id+p]=i.id+p;const root=k=>parent[k]===k?k:(parent[k]=root(parent[k]));for(const l of setup.links.filter(l=>l.kind==='wire'))parent[root(l.from+l.fromPort)]=root(l.to+l.toPort);const battery=batteries[0],hi=root(battery.id+'A'),lo=root(battery.id+'B');if(hi===lo){out.status='Short circuit: supply disabled. Add resistance.';return out;}const edges=all.filter(i=>i.type!=='battery'&&!states[i.id]?.broken&&(i.type!=='switch'||i.settings.closed)).map(i=>({i,a:root(i.id+'A'),b:root(i.id+'B'),r:i.type==='switch'?.01:i.settings.resistance}));let reachable=new Set([hi]);let changed=true;while(changed){changed=false;for(const e of edges)if(reachable.has(e.a)!==reachable.has(e.b)){reachable.add(e.a);reachable.add(e.b);changed=true;}}
 if(!reachable.has(lo)){out.status='Open circuit • no current';return out;}const unknown=[...reachable].filter(x=>x!==hi&&x!==lo),A=unknown.map(()=>unknown.map(()=>0)),b=unknown.map(()=>0);for(const e of edges){if(!reachable.has(e.a)||e.a===e.b)continue;for(const [a,c]of [[e.a,e.b],[e.b,e.a]]){let j=unknown.indexOf(a);if(j<0)continue;A[j][j]+=1/e.r;let k=unknown.indexOf(c);if(k>=0)A[j][k]-=1/e.r;else if(c===hi)b[j]+=battery.settings.voltage/e.r;}}const v=solve(A,b);if(v===null){out.status='Circuit topology cannot be resolved.';return out;}const value=n=>n===hi?battery.settings.voltage:n===lo?0:v[unknown.indexOf(n)]??0;let total=0;for(const e of edges){let voltage=reachable.has(e.a)?value(e.a)-value(e.b):0,current=voltage/e.r;out.values[e.i.id]={voltage:Math.abs(voltage),current:Math.abs(current),power:current*current*e.r};if(e.a===hi)total+=current;if(e.b===hi)total-=current;}out.values[battery.id]={voltage:battery.settings.voltage,current:total,power:total*battery.settings.voltage};out.status='DC resistive circuit • ideal wires; switch resistance 0.01 Ω';return out;}
export function step(setup,run,dt){if(!Number.isFinite(dt)||dt<=0||dt>1)throw Error('Time step must be between 0 and 1 second');run.time+=dt;const electrical=circuit(setup,run.states);run.circuitStatus=electrical.status;
 for(const i of setup.items){const s=run.states[i.id];if(kind(i)==='vessel'&&i.mixture.length){const mix=mixtureInfo(i.mixture);s.mix=mix;const q=setup.links.filter(l=>l.kind==='thermal'&&l.to===i.id).reduce((sum,l)=>{const a=setup.items.find(x=>x.id===l.from);return sum+(a.type==='cooler'?-1:1)*a.settings.power;},0);const old=s.vapor;s.h=Math.max(-CI*30*s.mass,Math.min((LF+CW*100+LV)*s.mass,s.h+q*dt));Object.assign(s,thermalState(s.h,s.mass));s.boiling=s.phase==='Boiling'&&q>0;s.bubbles=s.boiling||(!mix.unsupported&&mix.bubbles&&run.time<20);s.vaporRate=Math.max(0,s.vapor-old)*s.mass;for(const l of setup.links.filter(l=>l.kind==='tube'&&l.from===i.id)){for(const dest of setup.links.filter(k=>k.kind==='tube'&&k.from===l.to)){run.states[dest.to].condensate+=s.vaporRate*1000;}}}
 if(i.type==='burner')s.smoke=i.settings.power>0&&i.settings.oxygen<40;
 if(i.type==='chamber'&&!s.broken){s.stress+=dt*setup.links.filter(l=>l.kind==='tube'&&l.to===i.id).reduce((v,l)=>v+setup.items.find(a=>a.id===l.from).settings.rate,0);if(s.stress>=i.settings.limit){s.broken=true;s.burstAt=run.time;run.events.unshift({time:run.time,text:'Fictional chamber rupture: blast, fragments and smoke. Reset to repair. This threshold has no real-world meaning.'});}}
 if(kind(i)==='electrical'){Object.assign(s,electrical.values[i.id]||{voltage:0,current:0,power:0});if(i.type==='bulb'&&s.power>i.settings.rating*2&&!s.broken){s.broken=true;s.burstAt=run.time;run.events.unshift({time:run.time,text:'Lamp overload: illustrative equipment damage. The damaged lamp opens the circuit on the next time step.'});}s.smoke=s.broken&&run.time-s.burstAt<8;}
 if(i.type==='pendulum'){s.supported=setup.links.some(l=>l.kind==='support'&&l.to===i.id);s.period=2*Math.PI*Math.sqrt(i.settings.length/i.settings.gravity);s.angle=s.supported?i.settings.angle*Math.PI/180*Math.cos(2*Math.PI*run.time/s.period):0;}}
 return run;}
export function preset(name){let items=[],links=[];const add=(type,x,z)=>{let i=makeItem(type,'i'+(items.length+1),x,z);items.push(i);return i;};const link=(kind,a,b,ap='A',bp='A')=>links.push({kind,from:a.id,to:b.id,fromPort:ap,toPort:bp});
 if(name==='freeze'){const v=add('beaker',0,0);v.settings.temperature=5;v.mixture=[{id:'water',ml:50}];const c=add('cooler',-2.5,0);link('thermal',c,v);}
 if(name==='boil'){const v=add('flask',-2,0);v.settings.temperature=90;v.mixture=[{id:'water',ml:50}];const h=add('heater',-4,0);h.settings.power=1000;const c=add('condenser',.5,0),r=add('collector',3,0);link('thermal',h,v);link('tube',v,c);link('tube',c,r);}
 if(name==='smoke'){const b=add('burner',0,0);b.settings.oxygen=20;}
 if(name==='burst'){const p=add('pump',-2,0),c=add('chamber',1,0);link('tube',p,c);}
 if(name==='circuit'||name==='overload'){const b=add('battery',-2,1),l=add('bulb',1,1),s=add('switch',0,-2);if(name==='overload')b.settings.voltage=12;link('wire',b,l,'A','A');link('wire',l,s,'B','A');link('wire',s,b,'B','B');}
 if(name==='pendulum'){const s=add('stand',0,0),p=add('pendulum',1,0);link('support',s,p);}
 if(name==='mix'){const v=add('beaker',0,0);v.mixture=[{id:'calcium',ml:50},{id:'carbonate',ml:50}];}
 return {version:1,name:{freeze:'Freezing water',boil:'Boiling & condensation',smoke:'Flame & smoke',burst:'Fictional rupture demonstration',circuit:'Build a light circuit',overload:'Lamp overload',pendulum:'Custom pendulum',mix:'Precipitation'}[name]||'My custom experiment',items,links};}
